-- Aggregate only user-confirmed correction signals. This is intentionally
-- not a pattern store: no message text, correction values, reason, account
-- details, or executable regex is recorded or generated by this migration.

begin;

create table if not exists public.sms_learning_feedback (
  id                 uuid primary key default gen_random_uuid(),
  profile_id         uuid not null references public.profiles(id) on delete cascade,
  source_key_hash    text not null check (source_key_hash ~ '^[0-9a-f]{64}$'),
  sender_fingerprint text not null check (sender_fingerprint ~ '^[0-9a-f]{64}$'),
  fact_family        text not null check (fact_family in (
    'posted_movement', 'pending_or_failed_attempt', 'balance_snapshot',
    'bill_obligation', 'bill_payment', 'mandate_lifecycle',
    'card_identity_hint', 'security_or_service_alert', 'promotion'
  )),
  corrected_field   text not null check (corrected_field in (
    'entryKind', 'instrument', 'amountInr', 'availableBalanceInr',
    'currentBalanceInr', 'amountDueInr', 'minimumDueInr', 'amountRole',
    'dueDate', 'statementDate', 'asOfAt', 'mandateStatus', 'merchant',
    'cadenceDays', 'limitInr', 'accountLast4', 'last4', 'currency'
  )),
  created_at         timestamptz not null default now(),
  unique (profile_id, source_key_hash, fact_family, corrected_field)
);

comment on table public.sms_learning_feedback is
  'HMAC sender/fact-family/corrected-field signals from user-confirmed corrections. Contains no SMS body, field values, or free-text reason.';

create index if not exists idx_sms_learning_feedback_group
  on public.sms_learning_feedback (sender_fingerprint, fact_family, corrected_field, created_at desc);

create table if not exists public.sms_learning_candidate_decisions (
  id                 uuid primary key,
  sender_fingerprint text not null check (sender_fingerprint ~ '^[0-9a-f]{64}$'),
  fact_family        text not null,
  corrected_field    text not null,
  decision           text not null check (decision in ('manual_pattern_authoring', 'reject')),
  decided_by         uuid not null references public.profiles(id),
  decided_at         timestamptz not null default now(),
  unique (sender_fingerprint, fact_family, corrected_field)
);

alter table public.sms_learning_feedback enable row level security;
alter table public.sms_learning_feedback force row level security;
drop policy if exists sms_learning_feedback_owner on public.sms_learning_feedback;
create policy sms_learning_feedback_owner on public.sms_learning_feedback
  for insert to public
  with check (profile_id = pandapay.uid());
drop policy if exists sms_learning_feedback_admin_read on public.sms_learning_feedback;
create policy sms_learning_feedback_admin_read on public.sms_learning_feedback
  for select to public using (pandapay.is_admin());

alter table public.sms_learning_candidate_decisions enable row level security;
alter table public.sms_learning_candidate_decisions force row level security;
drop policy if exists sms_learning_candidate_decisions_admin on public.sms_learning_candidate_decisions;
create policy sms_learning_candidate_decisions_admin on public.sms_learning_candidate_decisions
  for all to public using (pandapay.is_admin()) with check (pandapay.is_admin());
revoke all on public.sms_learning_candidate_decisions from public, app_user;
revoke all on public.sms_learning_feedback from public, app_user;
grant insert on public.sms_learning_feedback to app_user;

create or replace function pandapay.sms_learning_candidates(p_limit integer default 100)
returns jsonb language plpgsql security definer
set search_path = pg_catalog, public, pandapay
as $$
declare v_candidates jsonb;
begin
  if not pandapay.is_admin() then raise exception 'admin required' using errcode = '42501'; end if;
  if p_limit < 1 or p_limit > 200 then raise exception 'invalid limit'; end if;
  select coalesce(jsonb_agg(to_jsonb(c) order by c.last_feedback_at desc), '[]'::jsonb)
    into v_candidates
    from (
      select (md5(f.sender_fingerprint || ':' || f.fact_family || ':' || f.corrected_field))::uuid as id,
             f.sender_fingerprint, f.fact_family, f.corrected_field,
             count(*)::int as feedback_count,
             count(distinct f.profile_id)::int as distinct_users,
             max(f.created_at) as last_feedback_at,
             d.decision, d.decided_at
        from public.sms_learning_feedback f
        left join public.sms_learning_candidate_decisions d
          on d.sender_fingerprint = f.sender_fingerprint
         and d.fact_family = f.fact_family
         and d.corrected_field = f.corrected_field
       group by f.sender_fingerprint, f.fact_family, f.corrected_field, d.decision, d.decided_at
      having count(distinct f.profile_id) >= 5
       order by max(f.created_at) desc
       limit p_limit
    ) c;
  return v_candidates;
end;
$$;

create or replace function pandapay.sms_learning_decide(p_candidate_id uuid, p_decision text, p_admin_id uuid)
returns jsonb language plpgsql security definer
set search_path = pg_catalog, public, pandapay
as $$
declare v_candidate record;
begin
  if not pandapay.is_admin() then raise exception 'admin required' using errcode = '42501'; end if;
  if p_decision not in ('manual_pattern_authoring', 'reject') then raise exception 'invalid decision'; end if;
  select f.sender_fingerprint, f.fact_family, f.corrected_field
    into v_candidate
    from public.sms_learning_feedback f
   group by f.sender_fingerprint, f.fact_family, f.corrected_field
  having count(distinct f.profile_id) >= 5
     and (md5(f.sender_fingerprint || ':' || f.fact_family || ':' || f.corrected_field))::uuid = p_candidate_id;
  if not found then return jsonb_build_object('ok', false, 'reason', 'not_eligible'); end if;

  insert into public.sms_learning_candidate_decisions
    (id, sender_fingerprint, fact_family, corrected_field, decision, decided_by, decided_at)
  values (p_candidate_id, v_candidate.sender_fingerprint, v_candidate.fact_family,
          v_candidate.corrected_field, p_decision, p_admin_id, now())
  on conflict (sender_fingerprint, fact_family, corrected_field)
  do update set decision = excluded.decision, decided_by = excluded.decided_by,
                decided_at = excluded.decided_at;
  return jsonb_build_object('ok', true, 'decision', p_decision);
end;
$$;

revoke all on function pandapay.sms_learning_candidates(integer) from public;
revoke all on function pandapay.sms_learning_decide(uuid, text, uuid) from public;
grant execute on function pandapay.sms_learning_candidates(integer) to app_user;
grant execute on function pandapay.sms_learning_decide(uuid, text, uuid) to app_user;

commit;
